actions.script:
gatewayDeviceId = gatewayDeviceId || System.getProperty("device_gateway_device_id") || null;
ready = false;
scopedDeviceIds = [];
controllerDeviceIds = [];
if (!gatewayDeviceId) {
    message = "No gateway identity: set the property device_gateway_device_id.";
    return;
}
const device = ec.entity.find("moqui.device.Device").condition("deviceId", gatewayDeviceId).one();
const physical = ec.entity.find("moqui.device.PhysicalDevice").condition("deviceId", gatewayDeviceId).one();
if (!device || !physical) {
    message = `Configured gateway ${gatewayDeviceId} does not exist as Device + PhysicalDevice.`;
    return;
}
const alive = (member) => member.statusId == null || member.statusId === 'DgmsAlive';
const roots = (ec.entity.find("moqui.device.DeviceGroupMember").condition("memberDeviceId", gatewayDeviceId)
    .condition("purposeEnumId", "DgmpEdgeGateway").list() || []).filter(alive).map(m => m.deviceId);
if (roots.length === 0) {
    message = `Gateway ${gatewayDeviceId} is not assigned to any DeviceGroup as DgmpEdgeGateway.`;
    return;
}
const controllerPurposes = ['DgmpProcessPLC', 'DgmpSafetyPLC', 'DgmpController', 'DgmpMotionController',
    'DgmpRemoteIO', 'DgmpSafetyRemoteIO', 'DgmpExtremeConditionRemoteIO'];
const visible = new Set(roots);
const controllers = new Set();
const pending = [...roots];
while (pending.length) {
    const groupId = pending.shift();
    for (const member of (ec.entity.find("moqui.device.DeviceGroupMember").condition("deviceId", groupId).list() || [])) {
        if (!alive(member)) continue;
        if (controllerPurposes.includes(member.purposeEnumId)) controllers.add(member.memberDeviceId);
        if (!visible.has(member.memberDeviceId)) {
            visible.add(member.memberDeviceId);
            pending.push(member.memberDeviceId);
        }
    }
}
scopedDeviceIds = [...visible];
controllerDeviceIds = [...controllers];
ready = true;
message = "ready";

const scope = ec.service.sync().name("moqui.device.gateway.SubscriptionServices.get#GatewayScope")
    .parameters({gatewayDeviceId: gatewayDeviceId}).call();
gatewayDeviceId = scope.gatewayDeviceId;
ready = scope.ready;
message = scope.message;
requestNames = [];
if (!ready) return;
const controllers = new Set(scope.controllerDeviceIds || []);
const types = ['DrtSubscribe', 'DrtEvent', 'DrtStateChange', 'DrtCyclic'];
const toNumber = (value) => value == null ? 999999 :
    (typeof value.toNumber === 'function' ? value.toNumber() : Number(value));
requestNames = (ec.entity.find("moqui.device.DeviceRequest").conditionDate("fromDate", "thruDate").list() || [])
    .filter(r => controllers.has(r.deviceId) && types.includes(r.requestTypeEnumId)
        && (r.runServiceName || '').startsWith('moqui.device.gateway.'))
    .sort((a, b) => (toNumber(a.priority) - toNumber(b.priority)) || (toNumber(a.sequenceNum) - toNumber(b.sequenceNum))
        || (a.requestName < b.requestName ? -1 : (a.requestName > b.requestName ? 1 : 0)))
    .map(r => r.requestName);

startedRequestNames = [];
failedRequestNames = [];
if (System.getProperty("device_gateway_restore_subscriptions") === "false") return;
const state = ec.service.sync().name("moqui.device.gateway.SubscriptionServices.get#SubscriptionState")
    .parameters({claimStartup: true}).call();
if (ec.message.hasError()) return;
let names = state.droppedRequestNames || [];
if (state.startupClaimed) {
    const startup = ec.service.sync().name("moqui.device.gateway.SubscriptionServices.get#StartupSubscriptions")
        .parameters({}).call();
    if (!startup.ready) {
        ec.logger.warn(`Device gateway subscriptions are not restored: ${startup.message}`);
    } else {
        const active = new Set(state.activeRequestNames || []);
        names = names.concat((startup.requestNames || []).filter(n => !active.has(n) && !names.includes(n)));
    }
}
for (const requestName of names) {
    try {
        ec.service.sync().name("moqui.device.DeviceServices.run#DeviceRequest")
            .parameters({requestName: requestName}).call();
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString());
        startedRequestNames.push(requestName);
    } catch (e) {
        failedRequestNames.push(requestName);
        ec.logger.warn(`Device gateway subscription ${requestName} did not start: ${e.message || e}`);
        ec.message.clearErrors();
    }
}
if (startedRequestNames.length || failedRequestNames.length) {
    ec.logger.info(`Device gateway subscriptions started: ${startedRequestNames.length}, failed: ${failedRequestNames.length}`);
}
